import React from "react";
import { clsx } from "clsx";

import { TableClasses } from "../table.styles";

export const TableEmptyState = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ children, className, ...rest }, ref) => (
  <div ref={ref} className={clsx(TableClasses.emptyState, className)} {...rest}>
    {children}
  </div>
));
TableEmptyState.displayName = "Table.EmptyState";
